const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return {
  json: {
    ...$input.first().json,
    since_iso: oneWeekAgo.toISOString(),
    now_iso: now.toISOString(),
    formatted_date: now.toISOString().split('T')[0]
  }
};

const config = $('Calculate 7-Day Window').first().json;

// 1. Process commits
const commitItems = $('Fetch Commits').all();
const commitList = commitItems.map(item => {
  const c = item.json;
  const message = (c.commit?.message || '').split('\n')[0];
  const author = c.commit?.author?.name || c.author?.login || 'unknown';
  const sha = (c.sha || '').substring(0, 7);
  return `- [${sha}] ${message} (@${author})`;
}).slice(0, 40);

// 2. Process merged PRs (filter by merged_at within the window)
const sinceDate = new Date(config.since_iso);
const prItems = $('Fetch Closed Pull Requests').all();
const mergedPrList = [];
for (const item of prItems) {
  const pr = item.json;
  if (pr.merged_at && new Date(pr.merged_at) >= sinceDate) {
    mergedPrList.push(`- PR #${pr.number}: ${pr.title} by @${pr.user?.login || 'anonymous'} (Merged: ${pr.merged_at.split('T')[0]})`);
  }
}

// 3. Process closed issues (filter out pull requests which GitHub returns in issues endpoint)
const issueItems = $('Fetch Closed Issues').all();
const closedIssueList = [];
for (const item of issueItems) {
  const iss = item.json;
  if (!iss.pull_request && iss.closed_at && new Date(iss.closed_at) >= sinceDate) {
    closedIssueList.push(`- Issue #${iss.number}: ${iss.title} (@${iss.user?.login || 'unknown'})`);
  }
}

const languagePrompt = config.language?.toUpperCase() === 'FR' 
  ? 'Rédige le résumé hebdomadaire en français professionnel.' 
  : 'Write the weekly summary in concise, professional English.';

const userPrompt = `You are an executive engineering manager. Summarize the following week of engineering activities for repository "${config.repo_owner}/${config.repo_name}" (Period: ${config.since_iso.split('T')[0]} to ${config.formatted_date}).

${languagePrompt}

### Input Data:
**Merged Pull Requests (${mergedPrList.length})**:
${mergedPrList.length > 0 ? mergedPrList.join('\n') : 'No pull requests merged this week.'}

**Closed Issues (${closedIssueList.length})**:
${closedIssueList.length > 0 ? closedIssueList.join('\n') : 'No issues closed this week.'}

**Key Commits (${commitList.length})**:
${commitList.length > 0 ? commitList.join('\n') : 'No commits recorded this week.'}

### Format Requirements:
1. 🚀 **Key Highlights & Shipments**: 2-3 bullet points outlining major feature releases or milestones.
2. 🛠️ **Bug Fixes & Maintenance**: Summary of resolved issues and stability improvements.
3. 📈 **Velocity & Stats**: Total commits, merged PRs, and closed issues.
4. Keep it engaging, formatted in clean Markdown, under 400 words.`;

return {
  json: {
    ...config,
    user_prompt: userPrompt,
    stats: {
      commits: commitList.length,
      merged_prs: mergedPrList.length,
      closed_issues: closedIssueList.length
    }
  }
};

const claudeResponse = $input.first().json;
const prevContext = $('Aggregate & Format Context').first().json;

const contentBlock = claudeResponse.content?.[0]?.text || 'No summary generated.';
const repo = `${prevContext.repo_owner}/${prevContext.repo_name}`;
const isDiscord = (prevContext.webhook_type || '').toLowerCase() === 'discord';

let webhookPayload;
if (isDiscord) {
  webhookPayload = {
    username: "Claude Dev Digest",
    avatar_url: "https://anthropic.com/favicon.ico",
    embeds: [
      {
        title: `📊 Weekly Engineering Digest: ${repo}`,
        description: contentBlock,
        color: 14457715,
        footer: {
          text: `Generated by Claude Sonnet • ${prevContext.formatted_date}`
        }
      }
    ]
  };
} else {
  // Slack Webhook payload
  webhookPayload = {
    text: `*Weekly Engineering Digest for ${repo}*\n\n${contentBlock}`,
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: `📊 Weekly Engineering Digest: ${repo}`
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: contentBlock
        }
      }
    ]
  };
}

return {
  json: {
    destination_url: prevContext.webhook_url,
    payload: webhookPayload,
    raw_summary: contentBlock
  }
};
